pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // Input is assumed non-empty per problem statement, but we still handle empty safely.
    a.into_iter()
        .map(|s| {
            // Ensure each inner list is non-empty, regardless of content.
            let mut parts: Vec<String> = if keepends {
                // Keep line endings: split_inclusive keeps the delimiter in each returned piece.
                s.split_inclusive('\n').map(|p| p.to_string()).collect()
            } else {
                // Drop line endings: split removes the delimiter.
                s.split('\n').map(|p| p.to_string()).collect()
            };

            if parts.is_empty() {
                parts.push(String::new());
            }
            parts
        })
        .collect()
}